``` {.python .cell-code}
def ranges_leaves(n, edges):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    inf = 10**18
    left = [inf] * (n + 1)
    right = [0] * (n + 1)
    par = [0] * (n + 1)
    leaves = 0
    st = [(1, 0)]
    while st:
        v, p = st.pop()
        if p == -1:
            if left[v] == inf:
                leaves += 1
                left[v] = right[v] = leaves
            if par[v]:
                left[par[v]] = min(left[par[v]], left[v])
                right[par[v]] = max(right[par[v]], right[v])
            continue
        par[v] = p
        st.append((v, -1))
        for c in adj[v]:
            if c != p:
                st.append((c, v))
    return [(left[v], right[v]) for v in range(1, n + 1)], leaves


