def average_of_levels(root):
    q = deque([root])
    out = []
    while q:
        s = len(q)
        total = 0
        for _ in range(s):
            u = q.popleft()
            total += u.val
            if u.left:
                q.append(u.left)
            if u.right:
                q.append(u.right)
        out.append(total / s)
    return out
