vector<double> averageOfLevels(TreeNode* root) {
    queue<TreeNode*> q;
    q.push(root);
    vector<double> out;
    while (!q.empty()) {
        int s = (int)q.size();
        long long total = 0;
        for (int i = 0; i < s; ++i) {
            auto u = q.front();
            q.pop();
            total += u->val;
            if (u->left) q.push(u->left);
            if (u->right) q.push(u->right);
        }
        out.push_back((double)total / s);
    }
    return out;
}
