def average_of_levels_dfs(root):
    sums, cnt = [], []

    def go(u, d):
        if u is None:
            return
        if len(sums) == d:
            sums.append(0)
            cnt.append(0)
        sums[d] += u.val
        cnt[d] += 1
        go(u.left, d + 1)
        go(u.right, d + 1)

    go(root, 0)
    return [sums[d] / cnt[d] for d in range(len(sums))]


