``` {.python .cell-code}
def zigzag_reverse(root):
    if root is None:
        return []
    q, out = deque([root]), []
    while q:
        level = []
        for _ in range(len(q)):
            u = q.popleft()
            level.append(u.val)
            if u.left:
                q.append(u.left)
            if u.right:
                q.append(u.right)
        if len(out) % 2 == 1:
            level.reverse()
        out.append(level)
    return out
