def zigzag_stacks(root):
    if root is None:
        return []
    cur, nxt = [root], []
    out, left_to_right = [], True
    while cur:
        row = []
        while cur:
            u = cur.pop()
            row.append(u.val)
            kids = (u.left, u.right) if left_to_right else (u.right, u.left)
            for c in kids:
                if c is not None:
                    nxt.append(c)
        out.append(row)
        cur, nxt = nxt, cur
        left_to_right = not left_to_right
    return out


