def recover_morris(root):
    first = second = prev = None

    def visit(u):
        nonlocal first, second, prev
        if prev is not None and prev.val > u.val:
            if first is None:
                first = prev
            second = u
        prev = u

    cur = root
    while cur:
        if cur.left is None:
            visit(cur)
            cur = cur.right
            continue
        p = cur.left
        while p.right is not None and p.right is not cur:
            p = p.right
        if p.right is None:
            p.right = cur
            cur = cur.left
        else:
            p.right = None
            visit(cur)
            cur = cur.right
    first.val, second.val = second.val, first.val


def inorder_vals(root):
    out = []
    inorder(root, out)
    return out


