def serialize(root):
    out = []

    def enc(u):
        if u is None:
            out.append("#")
            return
        out.append(str(u.val))
        enc(u.left)
        enc(u.right)

    enc(root)
    return ",".join(out)


def deserialize(data):
    tok = data.split(",")
    i = 0

    def dec():
        nonlocal i
        t = tok[i]
        i += 1
        if t == "#":
            return None
        node = Node(int(t))
        node.left = dec()
        node.right = dec()
        return node

    return dec()
```
