::: {#db30f71c .cell execution_count=72}
``` {.python .cell-code}
def increasing_bst(root):
    dummy = Node(0)
    prev, st, cur = dummy, [], root
    while cur is not None or st:
        while cur is not None:
            st.append(cur)
            cur = cur.left
        cur = st.pop()
        cur.left = None
        prev.right = cur
        prev = cur
        cur = cur.right
    return dummy.right

