def tree2str(root):
    def go(u):
        if u.left is None and u.right is None:
            return str(u.val)
        s = str(u.val) + "(" + (go(u.left) if u.left else "") + ")"
        if u.right:
            s += "(" + go(u.right) + ")"
        return s
    return go(root)

